css:
:root {
  --rv-accent: oklch(0.507 0.075 260.8);
  --rv-accent-soft: oklch(0.507 0.075 260.8 / 0.12);
  --rv-bg: oklch(0.16 0.006 260.8);
  --rv-bg-chart: oklch(0.19 0.006 260.8);
  --rv-bg-elev: oklch(0.205 0.006 260.8);
  --rv-block-gap: 3rem;
  --rv-brand: oklch(0.70 0.16 264);
  --rv-chart-ink: oklch(1 0 0);
  --rv-density: 1;
  --rv-down: oklch(0.68 0.17 25);
  --rv-font-display: Space Grotesk, Inter, sans-serif;
  --rv-font-mono: Geist Mono, JetBrains Mono, ui-monospace, monospace;
  --rv-font-text: Geist, Inter, system-ui, sans-serif;
  --rv-font-ui: Geist, Inter, system-ui, sans-serif;
  --rv-hold: oklch(0.78 0.14 70);
  --rv-ink: oklch(0.95 0.019 260.8);
  --rv-ink-faint: oklch(0.51 0.019 260.8);
  --rv-ink-soft: oklch(0.72 0.019 260.8);
  --rv-line-base: 1.65;
  --rv-link: oklch(0.602 0.075 260.8);
  --rv-measure: 42rem;
  --rv-radius-m: 12px;
  --rv-radius-s: 12px;
  --rv-report-max-width: 880px;
  --rv-rule: oklch(0.3 0.011 260.8);
  --rv-rule-soft: oklch(0.29 0.011 260.8);
  --rv-shadow-float: none;
  --rv-size-base: 18px;
  --rv-size-display: 50px;
  --rv-size-h1: 40px;
  --rv-size-h2: 32px;
  --rv-size-h3: 22px;
  --rv-size-small: 15px;
  --rv-up: oklch(0.70 0.15 150);
}
@media (max-width: 640px) {
:root {
  --rv-block-gap: 2rem;
  --rv-size-base: 17px;
  --rv-size-display: 38px;
  --rv-size-h1: 33px;
  --rv-size-h2: 28px;
  --rv-size-h3: 21px;
  --rv-size-small: 14px;
}
}
:root{color-scheme:dark}
:root{--rv-readout-rule:var(--rv-ink-faint)}
:root{--rv-motion-duration:560ms;--rv-motion-easing:cubic-bezier(0.33,1,0.68,1);--rv-motion-stagger:40ms;--rv-motion-distance:14px;--rv-motion-block:fade-up}
.rv-report__body blockquote{font-style:italic}
.rv-callout{border-top-width:1px}
.rv-report__title{letter-spacing:-0.02em}
.rv-chart{background:var(--rv-bg-chart);padding:1rem 1.25rem;border-radius:var(--rv-radius-m)}
.rv-chart.rv-chart--expanded{border:0;background:none;border-radius:0}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
